{
  "originalFormula": "E_{F} = E_{c} - 0.209 \, \\text{eV} + E_{v} + 0.9107 \, \\text{eV}",
  "genericFormula": "E_{F} = E_{c} + E_{v} + C",
  "description": "Esta fórmula representa a energia do nível de Fermi em um material semicondutor, que é a energia máxima que os elétrons podem ter a temperaturas absolutas próximas do zero. A fórmula mostra como essa energia é influenciada pelas energias de condução e de valência, além de um termo constante.",
  "concepts": [
    "Nível de Fermi",
    "Energia de condução",
    "Energia de valência",
    "Energia em semicondutores"
  ],
  "symbols": [
    {
      "symbol": "E_{F}",
      "description": "Representa a energia do nível de Fermi, que é a energia máxima ocupada por elétrons em um material a temperatura zero."
    },
    {
      "symbol": "E_{c}",
      "description": "Representa a energia da banda de condução, que é o nível de energia onde os elétrons podem se mover livremente e conduzir eletricidade."
    },
    {
      "symbol": "E_{v}",
      "description": "Representa a energia da banda de valência, que é o nível de energia onde os elétrons estão ligados aos átomos e não podem conduzir eletricidade."
    },
    {
      "symbol": "C",
      "description": "Representa um termo constante que pode incluir correções ou ajustes na energia, como a diferença de energia em relação a um ponto de referência."
    }
  ]
}
